
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_k_pbe3_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_k_pbe3", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([1.009452956165060e+02, 9.810966112154063e+01, 9.423681972027566e+01, 8.905540912463789e+01, 8.230783864809803e+01, 7.380260662835683e+01, 6.343525055328676e+01, 5.111519482647207e+01, 3.680111880829617e+01, 2.160650893823393e+01, 9.442133072599031e+00, 2.881259197887553e+00, 1.846946668578751e+00, 1.646151886364514e+00, 1.111503646019120e+00, 4.709941716983149e-01, 1.103917705087497e-01, 1.269152601312326e-02, 5.805991298413039e-04, 7.279840319927328e-06]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


